function longestNoTriple(a: number, b: number, c: number): string {
  const memo = new Map<string, string>();
  const go = (cnt: number[], last: number, run: number): string => {
    const key = cnt.join(",") + "|" + last + "|" + run;
    const hit = memo.get(key);
    if (hit !== undefined) return hit;
    let best = "";
    for (let i = 0; i < 3; i++) {
      if (cnt[i] === 0 || (i === last && run === 2)) continue;
      cnt[i]--;
      const s = "abc"[i] + go(cnt, i, i === last ? run + 1 : 1);
      cnt[i]++;
      if (s.length > best.length) best = s;
    }
    memo.set(key, best);
    return best;
  };
  return go([a, b, c], -1, 0);
}

