function longestNoTriple(a: number, b: number, c: number): string {
  const left: [number, string][] = [[a, "a"], [b, "b"], [c, "c"]];
  const out: string[] = [];
  while (true) {
    left.sort((x, y) => y[0] - x[0]);
    let placed = false;
    for (const p of left) {
      if (p[0] === 0) break;
      const n = out.length;
      if (n >= 2 && out[n - 1] === p[1] && out[n - 2] === p[1]) continue;
      out.push(p[1]);
      p[0]--;
      placed = true;
      break;
    }
    if (!placed) return out.join("");
  }
}

